{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Systematic review of direct access physiotherapy for musculoskeletal conditions in primary care: consequences for general practitioner workload, resource use, and organisation of care",
      "reason": "The title explicitly includes the phrase \"Systematic review\"."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Systematic review of direct access physiotherapy for musculoskeletal conditions in primary care: consequences for general practitioner workload, resource use, and organisation of care",
      "reason": "The title identifies the intervention (\"direct access physiotherapy\"), the population (\"musculoskeletal conditions in primary care\"), and the outcomes/objectives (\"consequences for general practitioner workload, resource use, and organisation of care\")."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The title does not contain supplementary information such as study design or update status, and this element is conditional; it is not required if the information is not present in the title."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Musculoskeletal disorders (MSDs) are frequent and disabling conditions in primary care and contribute substantially to general practitioners' (GPs) workload. Direct access (DA) to physiotherapy, allowing patients to consult physiotherapists without prior medical referral, has been proposed to streamline care, reduce delays, and optimise resource use.",
      "reason": "The text describes the current state of knowledge regarding musculoskeletal disorders and the proposed benefits of direct access to physiotherapy."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "This systematic review synthesized the effects of DA on GPs' practice and the organisation of primary care for adults with MSDs.",
      "reason": "The text explains the purpose and need for the review by stating it synthesizes the effects of direct access on GP practice and primary care organization."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not indicate that this is an update or replication of a previous systematic review, nor does it mention the existence of similar reviews that necessitate this specific one."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review focuses on a service delivery model (direct access to physiotherapy) rather than a specific clinical intervention with a biological or pharmacological mechanism of action."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not present a logic model, and while it discusses a complex delivery context, a formal logic model is not required for all such reviews."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "To assess the impact of DA to physiotherapy on general practice for adult MSDs.",
      "reason": "The review explicitly states its objective in the 'Objective' section."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Population: adults (≥ 18 years) with non-specific MSDs (i.e., musculoskeletal conditions without identified specific pathology such as fracture, inflammatory arthritis, or malignancy) managed in primary care; Intervention: DA to physiotherapy. Comparator: GP-referred pathway (referral-based usual care); Primary outcome: GP workload (number/frequency of GP consultations); Secondary outcomes: medication/imaging prescriptions, patientreported outcomes (pain, function, QoL), direct/indirect costs, safety",
      "reason": "The review explicitly defines the planned comparisons and outcomes using a PICO framework in the 'Eligibility Criteria (Pico Framework)' section."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Population: adults (≥ 18 years) with non-specific MSDs... managed in primary care; Intervention: DA to physiotherapy. Comparator: GP-referred pathway (referral-based usual care); Primary outcome: GP workload... Secondary outcomes: medication/imaging prescriptions, patientreported outcomes (pain, function, QoL), direct/indirect costs, safety; Designs included: RCTs and observational comparative studies (cohort, case-control, quasi-experimental).",
      "reason": "The manuscript explicitly defines the PICO components (Population, Intervention, Comparator, Outcomes) and the eligible study designs."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "Qualitative-only reports, case series, protocols, and non-peer-reviewed documents were excluded.",
      "reason": "The manuscript specifies exclusion criteria regarding publication type (qualitative-only, protocols, non-peer-reviewed), but does not explicitly state criteria regarding dissemination year or language."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not report excluding studies specifically because outcomes were not measured versus not reported; this distinction is not relevant to the reported exclusion criteria."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Given clinical and methodological heterogeneity across designs, settings, and outcomes, we conducted a narrative synthesis.",
      "reason": "The manuscript specifies that a narrative synthesis was used due to heterogeneity, which serves as the grouping method for the synthesis."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "This combination was chosen to capture both efficacy data from experimental designs (RCTs) and realworld organizational impacts (observational studies) often unavailable in experimental settings.",
      "reason": "The authors provide a clear rationale for the inclusion of both RCTs and observational studies."
    }
  ],
  "confidence": 95
}

